let careerRecordIdentity=null,careerRecordCompetition='all',careerRecordOwnership='all',careerRecordSort='goals',careerRecordExpanded=false,careerRecordReturn=null;
function careerCoverageMarkup(c){return '<p class="career-record-note">'+(c.partial?'남아 있는 기록만 집계합니다. '+c.fromYear+'시즌 '+(c.fromRound>c.totalRounds?c.totalRounds+'R 뒤':c.fromRound+'R')+(c.fromMinute?' · '+c.fromMinute+'분 이후':'')+'부터의 저장이며, 그 이전 기록은 추정하지 않습니다.':'경기 결과를 확정한 뒤 통산 기록에 반영합니다.')+(c.unassignedGoals?' 선수 미지정 득점 '+c.unassignedGoals+'골은 선수 득점에 합산하지 않습니다.':'')+' 승부차기 득점은 제외합니다.'+(c.cardsPartial?' 카드 기록이 없는 구버전 경기는 경고·퇴장을 집계하지 못합니다.':'')+'</p>';}
function careerPlayerMarkup(p){
 if(!p.valid)return '<p class="career-record-note">'+escapeText(p.reason)+'</p>';const esc=escapeText,t=p.total,games=careerRecordExpanded?p.games:p.games.slice(0,5);
 return '<div class="career-player-heading"><div><span>'+p.pos+' · '+(p.owned?'현재 우리 선수':'이적한 선수 · 기록 보존')+'</span><h3>'+esc(p.name)+'</h3></div><button type="button" id="career-record-back" class="secondary">전체 선수 기록</button></div><div class="career-record-kpis">'+[['출전',t.apps,'경기'],['득점',t.goals,'골'],['도움',t.assists,'개'],['뛴 시간',t.minutes,'분']].map(([label,n,unit])=>'<div><span>'+label+'</span><strong>'+n.toLocaleString('ko-KR')+'<small>'+unit+'</small></strong></div>').join('')+'</div><p class="career-record-note">선발 '+t.starts+'경기 · 경고 '+t.yellowCards+'회 · 퇴장 '+t.redCards+'회'+(p.pos==='GK'?' · 90분 무실점 '+t.cleanSheets+'경기':'')+(p.owned?' · 현재 계약의 성장 경험 '+p.currentXp.toLocaleString('ko-KR')+'분':'')+'. 통산 출전 시간과 현재 계약의 성장 경험은 별개입니다.</p><h4>시즌별 발자취</h4><div class="career-record-table"><table><thead><tr><th>시즌</th><th>출전</th><th>득점</th><th>도움</th><th>출전 시간</th>'+(p.pos==='GK'?'<th>무실점</th>':'')+'</tr></thead><tbody>'+p.seasons.map(r=>'<tr><th scope="row">'+r.year+'시즌<small>'+r.division+'부'+(r.partial?' · 일부 기록':'')+'</small></th><td>'+r.apps+'</td><td>'+r.goals+'</td><td>'+r.assists+'</td><td>'+r.minutes.toLocaleString('ko-KR')+'분</td>'+(p.pos==='GK'?'<td>'+r.cleanSheets+'</td>':'')+'</tr>').join('')+'</tbody></table></div><h4>실제로 뛴 경기</h4><ul class="career-record-games">'+games.map(g=>'<li><div><strong>'+g.year+'시즌 · '+esc(g.label)+'</strong><span>'+esc(g.opponent)+' · '+(g.home?'홈':'원정')+' · '+g.score[0]+':'+g.score[1]+'</span><small>'+(g.started?'선발':'교체')+' '+g.minutes+'분 · '+g.goals+'골 · '+g.assists+'도움</small></div><button type="button" class="secondary" data-career-game="'+esc(g.id)+'">경기 기록</button></li>').join('')+'</ul>'+(!p.games.length?'<p class="career-record-note">이 대회에서 확정된 출전 기록이 없습니다.</p>':'')+(p.games.length>5?'<button type="button" id="career-record-expand" class="secondary">'+(careerRecordExpanded?'최근 5경기만 보기':'출전 '+(p.games.length-5)+'경기 더 보기')+'</button>':'')+careerCoverageMarkup(p.coverage);
}
function careerTeamMarkup(m){
 const esc=escapeText,players=careerRecordExpanded?m.players:m.players.slice(0,12);
 return '<p class="career-record-intro">'+m.seasons+'개 시즌 · 확정 '+m.coverage.matches+'경기 · 우리 구단 '+m.goals+'골</p><div class="career-record-leaders">'+[['goals','최다 득점','골'],['assists','최다 도움','도움'],['minutes','최다 출전 시간','분'],['cleanSheets','골키퍼 무실점','경기']].map(([key,label,unit])=>{const lead=m.leaders[key];return '<article><span>'+label+'</span><strong>'+lead.value.toLocaleString('ko-KR')+'<small>'+unit+'</small></strong><p>'+(lead.players.length?lead.players.map(p=>esc(p.name)).join(' · ')+(lead.players.length>1?' · 공동 기록':''):'첫 기록을 기다립니다.')+'</p></article>';}).join('')+'</div><div class="career-record-filters"><label>선수 범위<select id="career-record-ownership">'+[['all','현재 + 이적 선수'],['current','현재 선수'],['departed','이적한 선수']].map(([v,n])=>'<option value="'+v+'"'+(v===careerRecordOwnership?' selected':'')+'>'+n+'</option>').join('')+'</select></label><label>정렬<select id="career-record-sort">'+[['goals','득점순'],['assists','도움순'],['minutes','출전 시간순'],['apps','출전 경기순'],['cleanSheets','무실점순']].map(([v,n])=>'<option value="'+v+'"'+(v===careerRecordSort?' selected':'')+'>'+n+'</option>').join('')+'</select></label></div><div class="career-record-table"><table><caption>선수 이름을 눌러 시즌별 기록과 출전 경기를 봅니다. 위 구단 최고 기록은 전체 등록 선수 기준입니다.</caption><thead><tr><th>선수</th><th>출전</th><th>득점</th><th>도움</th><th>출전 시간</th><th>무실점</th></tr></thead><tbody>'+players.map(p=>'<tr><th scope="row"><button type="button" data-career-player="'+esc(p.identity)+'">'+(p.rank?p.rank+'. ':'')+esc(p.name)+'</button><small>'+p.pos+' · '+(p.owned?'현재 선수':'이적 선수')+'</small></th><td>'+p.apps+'</td><td>'+p.goals+'</td><td>'+p.assists+'</td><td>'+p.minutes.toLocaleString('ko-KR')+'분</td><td>'+(p.pos==='GK'?p.cleanSheets:'—')+'</td></tr>').join('')+'</tbody></table></div>'+(!players.length?'<p class="career-record-note">이 범위에 남아 있는 선수 기록이 없습니다.</p>':'')+(m.players.length>12?'<button type="button" id="career-record-expand" class="secondary">'+(careerRecordExpanded?'상위 12명만 보기':'선수 '+(m.players.length-12)+'명 더 보기')+'</button>':'')+careerCoverageMarkup(m.coverage);
}
function renderCareerRecords(){
 const dialog=$('career-record-dialog');if(!dialog?.open)return;const m=careerRecordIdentity?CareerRecords.player(season,careerRecordIdentity,careerRecordCompetition):CareerRecords.summary(season,{competition:careerRecordCompetition,ownership:careerRecordOwnership,sort:careerRecordSort});
 dialog.innerHTML='<div class="career-record-head"><div><span class="eyebrow">CLUB CAREER RECORDS</span><h2 id="career-record-title">우리 구단 통산 선수 기록</h2></div><button type="button" id="close-career-record" class="secondary" aria-label="통산 기록 닫기">×</button></div><div class="career-record-body"><label class="career-record-competition">대회<select id="career-record-competition">'+[['all','전체 대회'],['league','리그'],['cup','국내컵'],['europe','유럽 대회']].map(([v,n])=>'<option value="'+v+'"'+(v===careerRecordCompetition?' selected':'')+'>'+n+'</option>').join('')+'</select></label>'+(careerRecordIdentity?careerPlayerMarkup(m):careerTeamMarkup(m))+'</div>';
 const close=()=>{dialog.close();careerRecordReturn?.focus?.({preventScroll:true});},redraw=id=>{renderCareerRecords();$(id)?.focus({preventScroll:true});};$('close-career-record').onclick=close;dialog.oncancel=e=>{e.preventDefault();close();};$('career-record-competition').onchange=e=>{careerRecordCompetition=e.target.value;careerRecordExpanded=false;redraw('career-record-competition');};
 if(careerRecordIdentity){const back=$('career-record-back');if(back)back.onclick=()=>{careerRecordIdentity=null;careerRecordExpanded=false;redraw('career-record-ownership');};}else{$('career-record-ownership').onchange=e=>{careerRecordOwnership=e.target.value;careerRecordExpanded=false;redraw('career-record-ownership');};$('career-record-sort').onchange=e=>{careerRecordSort=e.target.value;careerRecordExpanded=false;redraw('career-record-sort');};}
 dialog.querySelectorAll('[data-career-player]').forEach(b=>b.onclick=()=>{careerRecordIdentity=b.dataset.careerPlayer;careerRecordExpanded=false;renderCareerRecords();dialog.scrollTop=0;$('career-record-back')?.focus({preventScroll:true});});dialog.querySelectorAll('[data-career-game]').forEach(b=>b.onclick=()=>openMatchArchive(b.dataset.careerGame));const expand=$('career-record-expand');if(expand)expand.onclick=()=>{careerRecordExpanded=!careerRecordExpanded;redraw('career-record-expand');};
}
function openCareerRecords(identity=null){const dialog=$('career-record-dialog');if(!dialog)return;pauseForPlanning();careerRecordIdentity=identity;careerRecordExpanded=false;careerRecordReturn=document.activeElement;if(!dialog.open)dialog.showModal();renderCareerRecords();dialog.scrollTop=0;$('close-career-record').focus({preventScroll:true});}
